            '.logo-t{display:inline-grid;place-items:center;width:30px;height:30px;border-radius:9px;background:linear-gradient(135deg,var(--azul),#0a3a78);color:#fff;font-style:normal;font-weight:800;font-size:17px;border-bottom:3px '
