            '.neg{font-size:12px;color:#bcd0f5;margin:2px 0 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n'
            '.side nav{display:flex;flex-direction:column;gap:4px}.side nav a{padding:11px '
