            '.hero-panel h1{color:#fff;font-size:26px}.hp-sub{color:#bcd0f5;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}\n'
            '.card{background:#fff;border:1px solid var(--bor);border-radius:18px;padding:18px;margin-bottom:16px;box-shadow:0 8px 28px rgba(15,23,42,.05)}.scroll{overflow-x:auto}\n'
            '.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin-bottom:16px}.tile{background:#fff;border:1px solid var(--bor);border-top:4px solid '
