            '.fila{display:grid;grid-template-columns:1fr '
            '1fr;gap:12px}@media(max-width:600px){.fila{grid-template-columns:1fr}}.form{max-width:760px}.check{display:flex!important;gap:8px;align-items:center}.check input{width:auto;margin:0}\n'
