            'select{width:auto;flex:1;min-width:150px}.barra-filtro label{font-size:13px;color:var(--mut)}\n'
            '.en-linea{display:inline}.mov{display:flex;gap:6px;flex-wrap:wrap}.mov select{width:150px}.mov input{width:90px}.mov input[name=nota]{width:170px}\n'
            '.flash{padding:11px '
            '15px;border-radius:12px;margin-bottom:12px;font-weight:700}.flash.ok{background:#dcfce7;color:#047857}.flash.err{background:#fee2e2;color:#b91c1c}.aviso{background:#fef3c7;border:1px '
            'solid #fde68a;color:#b45309;padding:11px 15px;border-radius:12px;margin-bottom:12px;font-weight:600}\n'
            '.vacio{text-align:center;padding:26px}.barras{display:flex;align-items:flex-end;gap:5px;height:160px}.barra{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%}\n'
            '.barra i{display:block;width:100%;background:linear-gradient(180deg,var(--cian),var(--azul));border-radius:5px 5px 0 0}.barra small{font-size:10px;color:var(--mut);margin-top:4px}\n'
            '.pos{display:grid;grid-template-columns:1fr 380px;gap:16px;align-items:start}@media(max-width:1000px){.pos{grid-template-columns:1fr}}\n'
            '.pos-carro{position:sticky;top:12px}.grande{font-size:17px;padding:13px}.rejilla{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-top:12px}\n'
