            '#cobrar{margin-bottom:8px}#vaciar{width:100%}\n'
            '\n'
            '.centro{display:flex;align-items:center;justify-content:center;min-height:100vh;padding:16px;background:linear-gradient(135deg,#061b3f,#0020C2)}.caja-centro{background:#fff;border-radius:24px;padding:34px;max-width:440px;text-align:center;box-shadow:var(--sombra);border-bottom:6px '
            'solid var(--oro)}\n'
            '/* login (mismo estilo que EduTrack) */\n'
            '.login-page{min-height:100vh;background:#f1f5f9;display:flex;flex-direction:column}.login-page .lp-footer{margin-top:auto}.lp-nav{background:linear-gradient(90deg,#061b3f,#0a3a78 '
            '50%,#0020C2);color:#fff;padding:0 28px;height:58px;display:flex;align-items:center;justify-content:space-between;box-shadow:0 2px 12px rgba(0,0,0,.18)}\n'
            '.lp-nav .brand{display:flex;align-items:center;gap:10px;font-weight:800;font-size:18px}.lp-nav .brand b{color:var(--oro)}.lp-nav '
